'use client';

import { useRef, useState, useCallback, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { useDesignStore } from '@/lib/store';
import { Room } from './Room';
import { Lighting } from './Lighting';

export function Scene3D() {
  const { currentDesign } = useDesignStore();
  const controlsRef = useRef<any>(null);

  if (!currentDesign) return null;

  return (
    <div className="w-full h-full bg-gradient-to-b from-gray-900 to-gray-800">
      <Canvas
        camera={{ position: [0, 12, 25], fov: 60 }}
        shadows
        gl={{ antialias: true }}
      >
        <color attach="background" args={['#1a1a2e']} />
        <fog attach="fog" args={['#1a1a2e', 20, 100]} />
        
        <Lighting preset={currentDesign.roomSettings.lightingPreset} />
        
        {/* Just the Room - no SceneObject, no drag interactions */}
        <Room
          settings={currentDesign.roomSettings}
          templateId={currentDesign.templateId}
        />
        
        <OrbitControls
          ref={controlsRef}
          enablePan={true}
          enableZoom={true}
          enableRotate={true}
          minDistance={5}
          maxDistance={60}
          maxPolarAngle={Math.PI / 2 - 0.05}
        />
      </Canvas>
    </div>
  );
}
