'use client';

import { useMemo } from 'react';
import * as THREE from 'three';
import { useLoader } from '@react-three/fiber';
import type { RoomSettings, RoomType } from '@/lib/types';
import { roomTemplates } from '@/lib/templates';

interface RoomProps {
  settings: RoomSettings;
  templateId: RoomType;
}

export function Room({ settings, templateId }: RoomProps) {
  console.log('[DEBUG] Room - templateId:', templateId, 'settings:', settings);
  
  // Guard: settings must be defined
  if (!settings) {
    console.error('[DEBUG] Room - settings is undefined!');
    return null;
  }
  
  const template = roomTemplates.find(t => t.id === templateId);
  console.log('[DEBUG] Room - found template:', template);
  if (!template) {
    console.error('[DEBUG] Room - Template not found for id:', templateId);
  }
  const { width, depth, height } = template?.roomSize || { width: 40, depth: 60, height: 15 };
  console.log('[DEBUG] Room - roomSize:', { width, depth, height });
  
  // Ensure all settings have defaults
  const safeSettings = {
    wallColor: settings.wallColor || '#F8FAFC',
    floorColor: settings.floorColor || '#E2E8F0',
    floorMaterial: settings.floorMaterial || 'carpet',
    lightingPreset: settings.lightingPreset || 'warm',
    backdropStyle: settings.backdropStyle || 'none',
    backdropColor: settings.backdropColor || '#2DD4BF',
    backgroundImage: settings.backgroundImage,
    backgroundOpacity: settings.backgroundOpacity,
    backgroundScale: settings.backgroundScale,
    backgroundOffsetX: settings.backgroundOffsetX,
    backgroundOffsetZ: settings.backgroundOffsetZ,
  };

  const floorTexture = useMemo(() => {
    // Guard for SSR/client-side hydration safety
    if (typeof document === 'undefined') {
      return new THREE.Texture();
    }
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512;
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      return new THREE.Texture();
    }
    
    ctx.fillStyle = safeSettings.floorColor;
    ctx.fillRect(0, 0, 512, 512);
    
    if (safeSettings.floorMaterial === 'wood') {
      ctx.strokeStyle = 'rgba(0,0,0,0.1)';
      ctx.lineWidth = 2;
      for (let i = 0; i < 512; i += 32) {
        ctx.beginPath();
        ctx.moveTo(0, i);
        ctx.lineTo(512, i);
        ctx.stroke();
      }
    } else if (safeSettings.floorMaterial === 'tile') {
      ctx.strokeStyle = 'rgba(255,255,255,0.3)';
      ctx.lineWidth = 2;
      const tileSize = 64;
      for (let x = 0; x <= 512; x += tileSize) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, 512);
        ctx.stroke();
      }
      for (let y = 0; y <= 512; y += tileSize) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(512, y);
        ctx.stroke();
      }
    } else if (safeSettings.floorMaterial === 'grass') {
      ctx.fillStyle = '#4CAF50';
      ctx.fillRect(0, 0, 512, 512);
      for (let i = 0; i < 1000; i++) {
        ctx.fillStyle = `rgba(76, 175, 80, ${0.3 + Math.random() * 0.4})`;
        ctx.fillRect(Math.random() * 512, Math.random() * 512, 2, 4);
      }
    }
    
    const texture = new THREE.CanvasTexture(canvas);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(width / 2, depth / 2);
    return texture;
  }, [safeSettings.floorColor, safeSettings.floorMaterial, width, depth]);

  const isOutdoor = templateId === 'backyard' || templateId === 'patio';
  const hasBackgroundImage = !!safeSettings.backgroundImage;

  return (
    <group>
      {/* Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[width, depth]} />
        <meshStandardMaterial 
          map={floorTexture}
          color={safeSettings.floorMaterial === 'grass' ? '#ffffff' : safeSettings.floorColor}
          roughness={0.8}
          metalness={0.1}
        />
      </mesh>

      {/* Subtle Grid Reference - Visual only, positioned below drag plane */}
      <GridReference width={width} depth={depth} />

      {/* Background Image (Space Workflow) */}
      {hasBackgroundImage && (
        <BackgroundImageLayer 
          imageUrl={safeSettings.backgroundImage!}
          opacity={safeSettings.backgroundOpacity ?? 0.5}
          scale={safeSettings.backgroundScale ?? 1}
          offsetX={safeSettings.backgroundOffsetX ?? 0}
          offsetZ={safeSettings.backgroundOffsetZ ?? 0}
          width={width}
          depth={depth}
        />
      )}

      {/* Walls (only for indoor venues) */}
      {!isOutdoor && (
        <>
          {/* Back Wall */}
          <mesh position={[0, height / 2, -depth / 2]} receiveShadow>
            <planeGeometry args={[width, height]} />
            <meshStandardMaterial color={safeSettings.wallColor} />
          </mesh>
          
          {/* Left Wall */}
          <mesh position={[-width / 2, height / 2, 0]} rotation={[0, Math.PI / 2, 0]} receiveShadow>
            <planeGeometry args={[depth, height]} />
            <meshStandardMaterial color={safeSettings.wallColor} />
          </mesh>
          
          {/* Right Wall */}
          <mesh position={[width / 2, height / 2, 0]} rotation={[0, -Math.PI / 2, 0]} receiveShadow>
            <planeGeometry args={[depth, height]} />
            <meshStandardMaterial color={safeSettings.wallColor} />
          </mesh>
        </>
      )}

      {/* Backdrop */}
      {safeSettings.backdropStyle !== 'none' && (
        <Backdrop style={safeSettings.backdropStyle} color={safeSettings.backdropColor} width={width} />
      )}
    </group>
  );
}

// Subtle grid reference for spatial alignment
function GridReference({ width, depth }: { width: number; depth: number }) {
  const gridTexture = useMemo(() => {
    // Guard for SSR/client-side hydration safety
    if (typeof document === 'undefined') {
      return new THREE.Texture();
    }
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 512;
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      return new THREE.Texture();
    }
    
    // Clear
    ctx.clearRect(0, 0, 512, 512);
    
    // Draw subtle grid lines
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
    ctx.lineWidth = 1;
    
    // Major grid lines every 64px (approx 2 meters)
    const gridSize = 64;
    
    for (let x = 0; x <= 512; x += gridSize) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, 512);
      ctx.stroke();
    }
    
    for (let y = 0; y <= 512; y += gridSize) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(512, y);
      ctx.stroke();
    }
    
    const texture = new THREE.CanvasTexture(canvas);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(width / 4, depth / 4);
    return texture;
  }, [width, depth]);

  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]}>
      <planeGeometry args={[width, depth]} />
      <meshBasicMaterial
        map={gridTexture}
        transparent
        opacity={0.3}
        side={THREE.DoubleSide}
        depthWrite={false}
      />
    </mesh>
  );
}

// Background image component for space workflow
function BackgroundImageLayer({ 
  imageUrl, 
  opacity, 
  scale, 
  offsetX, 
  offsetZ,
  width,
  depth,
}: { 
  imageUrl: string; 
  opacity: number;
  scale: number;
  offsetX: number;
  offsetZ: number;
  width: number;
  depth: number;
}) {
  // Create a texture from the image URL
  const texture = useMemo(() => {
    const loader = new THREE.TextureLoader();
    const tex = loader.load(imageUrl);
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.LinearFilter;
    return tex;
  }, [imageUrl]);
  
  return (
    <mesh 
      rotation={[-Math.PI / 2, 0, 0]} 
      position={[offsetX, 0.01, offsetZ]}
    >
      <planeGeometry args={[width * scale, depth * scale]} />
      <meshBasicMaterial 
        map={texture}
        transparent
        opacity={opacity}
        side={THREE.DoubleSide}
        depthWrite={false}
      />
    </mesh>
  );
}

function Backdrop({ style, color, width }: { style: string; color: string; width: number }) {
  if (style === 'curtain') {
    return (
      <group position={[0, 4, -width / 2 + 2]}>
        {/* Curtain panels */}
        <mesh position={[-3, 0, 0]} castShadow>
          <boxGeometry args={[4, 8, 0.2]} />
          <meshStandardMaterial color={color} />
        </mesh>
        <mesh position={[3, 0, 0]} castShadow>
          <boxGeometry args={[4, 8, 0.2]} />
          <meshStandardMaterial color={color} />
        </mesh>
        {/* Swag */}
        <mesh position={[0, 3, 0.1]} castShadow>
          <cylinderGeometry args={[1.5, 1.5, 0.3, 32]} />
          <meshStandardMaterial color={color} />
        </mesh>
      </group>
    );
  }

  if (style === 'arch') {
    return (
      <group position={[0, 0, -width / 2 + 3]}>
        {/* Arch pillars */}
        <mesh position={[-3, 3.5, 0]} castShadow>
          <cylinderGeometry args={[0.3, 0.3, 7, 16]} />
          <meshStandardMaterial color={color} />
        </mesh>
        <mesh position={[3, 3.5, 0]} castShadow>
          <cylinderGeometry args={[0.3, 0.3, 7, 16]} />
          <meshStandardMaterial color={color} />
        </mesh>
        {/* Arch top */}
        <mesh position={[0, 7, 0]} castShadow>
          <torusGeometry args={[3, 0.3, 16, 32, Math.PI]} />
          <meshStandardMaterial color={color} />
        </mesh>
        {/* Flowers */}
        {[...Array(8)].map((_, i) => (
          <mesh
            key={i}
            position={[
              -3 + (i * 6) / 7,
              7 + Math.sin((i / 7) * Math.PI) * 3,
              0.3
            ]}
            castShadow
          >
            <sphereGeometry args={[0.15, 8, 8]} />
            <meshStandardMaterial color="#FF69B4" />
          </mesh>
        ))}
      </group>
    );
  }

  if (style === 'wall') {
    return (
      <mesh position={[0, 3, -width / 2 + 1]} receiveShadow>
        <planeGeometry args={[width * 0.8, 6]} />
        <meshStandardMaterial color={color} />
      </mesh>
    );
  }

  return null;
}
